css:
.split-hero {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 3.5rem;
  align-items: center;
  max-width: 1200px;
  margin: 4rem auto;
  padding: 0 1.5rem;
}

.editorial-kicker {
  display: block;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
}

.split-hero-title {
  font-family: var(--font-heading), serif;
  font-size: 3.5rem;
  line-height: 1.08;
  letter-spacing: -0.025em;
  color: var(--text-primary);
  margin: 0 0 1.5rem;
}

.split-hero-dek {
  font-size: 1.15rem;
  line-height: 1.65;
  color: var(--text-muted);
  margin: 0 0 2rem;
  max-width: 54ch;
}

.split-hero-actions {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.hero-btn-primary {
  display: inline-block;
  text-decoration: none;
  background: var(--text-primary);
  color: var(--canvas);
  padding: 0.75rem 1.6rem;
  border-radius: var(--radius-md, 8px);
  font-weight: 500;
  transition: opacity 0.15s ease;
}

.hero-btn-primary:hover {
  opacity: 0.88;
}

.hero-meta-read {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.editorial-frame {
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: var(--radius-lg, 12px);
  padding: 1.5rem;
}

.frame-caption {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1rem;
}

.frame-graphic {
  height: 280px;
  background: var(--canvas);
  border: 1px dashed var(--border);
  border-radius: var(--radius-md, 8px);
}

@media (max-width: 860px) {
  .split-hero {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .split-hero-title {
    font-size: 2.5rem;
  }
}
